for name,pairs in v15_restore.items():
    p=root/'fg'/name
    s=p.read_text(encoding='utf-8')
    for old,new in pairs:
        if s.count(old)!=1:
            raise RuntimeError(f'V15 restore patch: expected one match in {name}: {old[:100]}')
        s=s.replace(old,new,1)
    p.write_text(s,encoding='utf-8',newline='\n')
with (root/'fg'/'README.md').open('a',encoding='utf-8') as f:
    f.write('\n## V15 lifecycle restoration\nThe launcher stays open. The same executable runs a hidden GPU worker; Stop and target exit request ordinary shutdown first and terminate only that FG child if it stalls. CUDA capture is normalized to the initial game client dimensions before optical flow if NvFBC returns a different size. Vulkan remains windowed and requests no automatic fullscreen-exclusive ownership when supported. No Windows display-mode calls.\n')
print('V15 game-client sizing and isolated Stop/exit lifecycle applied.')

