for name,pairs in flow_scale.items():
    p=root/'fg'/name
    s=p.read_text(encoding='utf-8')
    for old,new in pairs:
        if s.count(old)!=1:
            raise RuntimeError(f'Flow scale patch: expected one match in {name}: {old[:100]}')
        s=s.replace(old,new,1)
    p.write_text(s,encoding='utf-8',newline='\n')
(root/'fg'/'compile-kernels.py').write_text("# Offline build-time CUDA compiler: no NVRTC DLL required in the app.\nfrom pathlib import Path\nimport ctypes as C, os, subprocess, sys\nroot=Path(__file__).resolve().parent\nsrc=root/'src'\ncuda=os.environ.get('CUDA_PATH','')\nnvcc=Path(cuda)/'bin'/'nvcc.exe'\nif cuda and nvcc.is_file():\n    subprocess.run([str(nvcc),'-std=c++14','-O3','-ptx','-arch=compute_75',str(src/'predict.cu'),'-o',str(src/'predict.ptx')],check=True)\n    sys.exit(0)\ntarget=root/'.ci-nvrtc'\nsubprocess.run([sys.executable,'-m','pip','install','--disable-pip-version-check','--no-deps','--target',str(target),'nvidia-cuda-nvrtc-cu12==12.8.93'],check=True)\ndll=next(target.rglob('nvrtc64_120_0.dll'),None)\nif not dll: raise RuntimeError('NVRTC compiler DLL missing')\ncookie=os.add_dll_directory(str(dll.parent))\nlib=C.CDLL(str(dll))\n# All NVRTC APIs use C calling convention and return nvrtcResult (int).\ndef check(result,step):\n    if result: raise RuntimeError(f'{step}: NVRTC error {result}')\np=C.c_void_p()\n# NVRTC built-in CUDA headers provide texture intrinsics and vector types.\nsource=(src/'predict.cu').read_bytes()\nheader=(src/'pixel_types.h').read_bytes()\nnames=(C.c_char_p*1)(b'pixel_types.h')\nheaders=(C.c_char_p*1)(header)\ncheck(lib.nvrtcCreateProgram(C.byref(p),C.c_char_p(source),C.c_char_p(b'predict.cu'),1,headers,names),'Create program')\ntry:\n    opts=[b'--std=c++14',b'--gpu-architecture=compute_75',b'--device-as-default-execution-space']\n    if os.environ.get('CUDA_INCLUDE'):opts.append(('--include-path='+os.environ['CUDA_INCLUDE']).encode())\n    a=(C.c_char_p*len(opts))(*opts)\n    result=lib.nvrtcCompileProgram(p,len(opts),a)\n    n=C.c_size_t()\n    check(lib.nvrtcGetProgramLogSize(p,C.byref(n)),'Log size')\n    log=C.create_string_buffer(n.value)\n    check(lib.nvrtcGetProgramLog(p,log),'Log')\n    print(log.value.decode(errors='replace'))\n    check(result,'Compile CUDA kernels')\n    check(lib.nvrtcGetPTXSize(p,C.byref(n)),'PTX size')\n    out=C.create_string_buffer(n.value)\n    check(lib.nvrtcGetPTX(p,out),'PTX')\n    data=out.value\n    for entry in (b'stageFlowTexture',b'stageFlowScaled',b'stageFlowInput',b'renderFrame',b'sceneGate'):\n        if entry not in data: raise RuntimeError('Missing kernel '+entry.decode())\n    (src/'predict.ptx').write_bytes(data)\nfinally:\n    lib.nvrtcDestroyProgram(C.byref(p))\nprint('Rebuilt embedded CUDA PTX with scaled optical flow.')\n",encoding='utf-8',newline='\n')
with (root/'fg'/'README.md').open('a',encoding='utf-8') as f:
    f.write('\n## NvOFA resolution\nNative (100%) by default; 10–100% in 5-point steps. Stop, select, Start. The requested scale is clamped to queried driver dimension limits. Fused grayscale/downsample into persistent NvOFA input buffers on its separate worker stream; cached texture hardware filtering where alignment permits, fused software sampling otherwise. Previous staged frame reused. No full-resolution intermediate for OFA. Real color and presentation dimensions unchanged; vector units and geometry use actual OFA dimensions. No runtime NVRTC dependency.\n')
print('Adjustable NvOFA resolution patch applied.')
